battman.net_src:
var st = states || {};
function day(e) { var x = st[e]; return x && x.attributes ? parseFloat(x.attributes.day) : NaN; }  /* Battman: missing total = unknown, not $0 */
var net = day(S.sell_total_entity) - day(S.buy_total_entity) - (parseFloat(a.dailyNetworkCharge) || 0);
var ts = parseFloat(a.netTargetSellPrice) || 0, tb = parseFloat(a.netTargetBuyPrice) || 0;
function met(v) {
  if (!v || typeof v !== "string" || v.indexOf("|") < 0) return null;
  var p = v.split("|"), t = new Date(p[0].trim().replace(/\.\d+/, ""));
  if (isNaN(t.getTime())) return null;
  var n = new Date();
  if (t.getFullYear() !== n.getFullYear() || t.getMonth() !== n.getMonth() || t.getDate() !== n.getDate()) return null;
  return { t: t, v: parseFloat(p[1]) || 0 };
}
function money(v) { if (isNaN(v)) return "—"; var n = Math.abs(v) < 0.005 ? 0 : v; return (n < 0 ? "\u2212" : "") + "$" + Math.abs(n).toFixed(2); }
var mode = ts !== 0 ? "sell" : (tb !== 0 ? "buy" : "");
var tgt = mode === "sell" ? ts : tb;
var sm = met(a.netTargetSellMet), bm = met(a.netTargetBuyMet), metK = "";
if (!mode) { if (sm && (!bm || sm.t >= bm.t)) metK = "sell"; else if (bm) metK = "buy"; }
var rem = mode === "sell" ? tgt - net : (mode === "buy" ? net - tgt : 0);
if (rem < 0) rem = 0;
return { net: net, mode: mode, target: tgt, be: mode !== "" && Math.abs(tgt) < 0.005, rem: rem, met: metK, metAt: metK === "sell" ? sm.t : (metK === "buy" ? bm.t : null), active: mode !== "" || metK !== "", money: money };

battman.timer_sheet_src:
var C = "var(--battman-blue)";
var pad = L.pad, clk = L.clk;
function HH() { return L.hass(); }
function T() { var s = HH().states[TMR]; return s || { state: "idle", attributes: {} }; }
function remS(t) {
  if (t.state !== "active" || !t.attributes || !t.attributes.finishes_at) return null;
  var ms = new Date(t.attributes.finishes_at) - new Date();
  return ms > 0 ? Math.round(ms / 1000) : 0;
}
function done() { if (typeof CLOSE === "function") CLOSE(); }
function startSec(sec) {
  if (!(sec > 0)) return;
  HH().callService("timer", "start", { entity_id: TMR, duration: Math.round(sec) });
  done();
}
function addSec(sec) {
  var cur = remS(T()) || 0;
  HH().callService("timer", "start", { entity_id: TMR, duration: Math.round(cur + sec) });
  done();
}
var q = function (s) { return root.querySelector(s); };
var live = T().state === "active";
var CH = "height:30px;display:inline-flex;align-items:center;padding:0 11px;border-radius:6px;background:var(--battman-surface-card);cursor:pointer;font-size:12px;font-weight:800;margin:0 5px 5px 0";
var LB = "font-size:9px;font-weight:800;letter-spacing:0.12em;text-transform:uppercase;color:var(--battman-text-dim);margin-bottom:6px";
var IN = "width:100%;box-sizing:border-box;height:36px;background:var(--battman-surface-card);border:1px solid var(--battman-blue-border);border-radius:6px;color:var(--battman-text-bright);font-size:16px;font-weight:800;text-align:center;padding:0 4px;font-family:var(--battman-font);color-scheme:dark";
var head = live
  ? "<div style=\"display:flex;align-items:baseline;gap:8px;margin-bottom:13px\"><span id=\"sh-cd\" style=\"font-size:26px;font-weight:800;color:" + C + ";font-variant-numeric:tabular-nums\"></span><span id=\"sh-un\" style=\"font-size:12px;font-weight:700;color:" + C + "\"></span></div>"
  : "<div style=\"font-size:13px;font-weight:800;color:var(--battman-text-dim);margin-bottom:13px\">Timer is off</div>";
var ext = "";
[["+15m", 900], ["+30m", 1800], ["+1h", 3600], ["+2h", 7200]].forEach(function (e) {
  ext += "<span class=\"sh-x bmb\" data-s=\"" + e[1] + "\" style=\"" + CH + ";border:1px solid var(--battman-blue-border);color:" + C + "\">" + (live ? e[0] : e[0].replace("+", "")) + "</span>";
});
var runs = L.runUntilList(HH());
var run = "";
runs.forEach(function (r) {
  run += "<span class=\"sh-r bmb\" data-at=\"" + r[2] + "\" data-s=\"" + r[1] + "\" style=\"" + CH + ";border:1px solid var(--battman-border-neutral-soft);color:var(--battman-text-muted)\">" + r[0] + "</span>";
});
root.innerHTML = "<style>.bmb{transition:filter .1s,transform .1s}.bmb:active{transform:scale(0.94);filter:brightness(1.6)}</style>"
  + head
  + "<div style=\"" + LB + "\">" + (live ? "Extend" : "Start for") + "</div><div style=\"margin-bottom:12px\">" + ext + "</div>"
  + "<div style=\"" + LB + "\">Run until</div><div style=\"margin-bottom:11px\">" + run + "</div>"
  + "<div style=\"display:flex;gap:8px;align-items:flex-end;margin-bottom:8px\">"
  +   "<div style=\"flex:1\"><div style=\"" + LB + ";color:" + C + "\">Set until</div><input id=\"sh-u\" type=\"time\" style=\"" + IN + "\"></div>"
  +   "<div style=\"color:var(--battman-text-dim);font-size:10px;font-weight:700;padding-bottom:11px\">or</div>"
  +   "<div style=\"flex:1\"><div style=\"" + LB + ";color:" + C + "\">Duration h</div><input id=\"sh-d\" type=\"number\" min=\"0\" max=\"48\" step=\"0.25\" placeholder=\"\u2014\" style=\"" + IN + "\"></div>"
  + "</div>"
  + "<div id=\"sh-pv\" style=\"font-size:11px;font-weight:700;color:var(--battman-text-dim);text-align:center;min-height:16px;margin-bottom:12px\"></div>"
  + "<div style=\"display:flex;gap:6px\">"
  +   (live ? "<div id=\"sh-cx\" class=\"bmb\" style=\"flex:1;text-align:center;padding:9px 4px;border-radius:6px;font-size:10px;font-weight:800;letter-spacing:0.08em;text-transform:uppercase;cursor:pointer;background:transparent;color:var(--battman-darkred);border:1px solid var(--battman-darkred-border-light)\">Cancel timer</div>" : "")
  +   "<div id=\"sh-ok\" class=\"bmb\" style=\"flex:1;text-align:center;padding:9px 4px;border-radius:6px;font-size:10px;font-weight:800;letter-spacing:0.08em;text-transform:uppercase;cursor:pointer;background:var(--battman-blue-soft-bg);color:" + C + ";border:1px solid var(--battman-blue-border)\">Set</div>"
  + "</div>";
function preview() {
  q("#sh-pv").innerHTML = L.preview(q("#sh-d").value, q("#sh-u").value, "pick a duration or an exact finish time");
}
root.querySelectorAll(".sh-x").forEach(function (el) {
  el.onclick = function () { var s = parseFloat(el.getAttribute("data-s")); if (live) addSec(s); else startSec(s); };
});
root.querySelectorAll(".sh-r").forEach(function (el) {
  el.onclick = function () { var at=el.getAttribute("data-at"); startSec(at?L.nextAt(at).sec:parseFloat(el.getAttribute("data-s"))); };
});
q("#sh-u").oninput = function () { if (this.value) q("#sh-d").value = ""; preview(); };
q("#sh-d").oninput = function () { if (this.value) q("#sh-u").value = ""; preview(); };
q("#sh-ok").onclick = function () { startSec(L.timerSec(q("#sh-d"), q("#sh-u"))); };
var cx = q("#sh-cx");
if (cx) cx.onclick = function () { HH().callService("timer", "cancel", { entity_id: TMR }); done(); };
function tick() {
  var cd = q("#sh-cd"); if (!cd) return;
  var t = T(), s = remS(t);
  if (s === null) { cd.textContent = "OFF"; return; }
  cd.textContent = Math.floor(s / 3600) + ":" + pad(Math.floor((s % 3600) / 60)) + ":" + pad(s % 60);
  q("#sh-un").textContent = "until " + clk(new Date(t.attributes.finishes_at));
}
preview();
tick();
if (root.bmShTick) clearInterval(root.bmShTick);
root.bmShTick = setInterval(function () {
  if (!root.isConnected) { clearInterval(root.bmShTick); root.bmShTick = null; return; }
  tick();
}, 1000);
